CREATE OR REPLACE FUNCTION public.ds_acquire_property_evidence_lease(p_key text, p_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare acquired integer;
begin
  insert into public.property_evidence_leases(key, token) values (p_key, p_token)
    on conflict (key) do update
      set token = excluded.token, created_at = now()
      where public.property_evidence_leases.created_at < now() - interval '15 minutes';
  get diagnostics acquired = row_count;
  return acquired = 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.ds_annotate_provider_attempt(p_usage_id uuid, p_budget_usage_id uuid, p_request_id uuid, p_report_id uuid, p_origin text, p_evidence_outcome text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(auth.role(),'') <> 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if;
  if p_request_id is null or p_origin is null or p_origin not in ('user','test','validation','system')
    or p_evidence_outcome is not null and p_evidence_outcome not in ('ACCEPTED','IDENTITY_REJECTED','NOT_FOUND','EMPTY')
    then raise exception 'INVALID_PROVIDER_TRACE'; end if;
  if p_usage_id is not null then
    update public.external_provider_usage set
      origin = case when request_id is null then p_origin else origin end,
      request_id = coalesce(request_id,p_request_id), report_id = coalesce(report_id,p_report_id),
      evidence_outcome = coalesce(evidence_outcome,p_evidence_outcome)
    where id=p_usage_id and (request_id is null or request_id=p_request_id)
      and (report_id is null or report_id is not distinct from p_report_id);
    if not found then raise exception 'PROVIDER_TRACE_ATTEMPT_NOT_FOUND'; end if;
  end if;
  if p_budget_usage_id is not null then
    update public.maxxis_provider_budget_usage set
      origin = case when request_id is null then p_origin else origin end,
      request_id = coalesce(request_id,p_request_id), report_id = coalesce(report_id,p_report_id),
      evidence_outcome = coalesce(evidence_outcome,p_evidence_outcome)
    where id=p_budget_usage_id and (request_id is null or request_id=p_request_id)
      and (report_id is null or report_id is not distinct from p_report_id);
    if not found then raise exception 'PROVIDER_TRACE_BUDGET_NOT_FOUND'; end if;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.ds_reserve_external_provider_usage(p_provider text, p_operation text, p_property_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT NULL::uuid, p_hard_limit integer DEFAULT 45)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_usage_id uuid; v_consumed integer; v_month_key integer;
begin
  if p_provider <> 'rentcast'
     or p_operation not in ('property_lookup', 'property_value_avm', 'property_sold_search') then
    raise exception using errcode = '22023', message = 'INVALID_PROVIDER_USAGE_RESERVATION';
  end if;
  if p_hard_limit < 1 or p_hard_limit > 45 then
    raise exception using errcode = '22023', message = 'INVALID_PROVIDER_HARD_LIMIT';
  end if;
  v_month_key := (extract(year from timezone('utc', now()))::integer * 100)
    + extract(month from timezone('utc', now()))::integer;
  perform pg_advisory_xact_lock(hashtext(p_provider), v_month_key);
  select count(*)::integer into v_consumed from public.external_provider_usage
   where provider = p_provider
     and created_at >= date_trunc('month', timezone('utc', now())) at time zone 'utc'
     and created_at < (date_trunc('month', timezone('utc', now())) + interval '1 month') at time zone 'utc'
     and (status = 'reserved' or billable_success = true);
  if v_consumed >= p_hard_limit then
    raise exception using errcode = 'P0001', message = 'MONTHLY_PROVIDER_LIMIT_REACHED';
  end if;
  insert into public.external_provider_usage (
    provider, operation, property_id, user_id, status, billable_success, was_cache_hit
  ) values (
    p_provider, p_operation, p_property_id, p_user_id, 'reserved', false, false
  ) returning id into v_usage_id;
  return v_usage_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.ds_reserve_maxxis_provider_budget(p_user_id uuid, p_property_id uuid, p_plan text, p_bucket text, p_total_budget integer, p_chat_percent integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_plan text := upper(trim(coalesce(p_plan, '')));
  v_bucket text := lower(trim(coalesce(p_bucket, '')));
  v_chat_limit integer;
  v_bucket_limit integer;
  v_consumed integer;
  v_month_key integer;
  v_id uuid;
begin
  if p_user_id is null or v_plan not in ('PRO', 'ENTERPRISE') or v_bucket not in ('chat', 'report') then
    raise exception using errcode = '22023', message = 'INVALID_PROVIDER_BUDGET_REQUEST';
  end if;
  if p_total_budget < 1 or p_total_budget > 45 or p_chat_percent < 0 or p_chat_percent > 100 then
    raise exception using errcode = '22023', message = 'INVALID_PROVIDER_BUDGET_CONFIG';
  end if;

  v_chat_limit := floor((p_total_budget * p_chat_percent)::numeric / 100)::integer;
  v_bucket_limit := case when v_bucket = 'chat' then v_chat_limit else p_total_budget - v_chat_limit end;
  if v_bucket_limit <= 0 then
    raise exception using errcode = 'P0001', message = 'PLAN_PROVIDER_BUDGET_EXHAUSTED';
  end if;

  v_month_key := extract(year from timezone('utc', now()))::integer * 100
    + extract(month from timezone('utc', now()))::integer;
  perform pg_advisory_xact_lock(hashtext('maxxis-provider:' || p_user_id::text || ':' || v_bucket), v_month_key);

  select count(*)::integer into v_consumed
    from public.maxxis_provider_budget_usage usage
   where usage.user_id = p_user_id
     and usage.bucket = v_bucket
     and usage.created_at >= date_trunc('month', timezone('utc', now())) at time zone 'utc'
     and usage.created_at < (date_trunc('month', timezone('utc', now())) + interval '1 month') at time zone 'utc'
     and (usage.status = 'reserved' or usage.billable_success = true);

  if v_consumed >= v_bucket_limit then
    raise exception using errcode = 'P0001', message = 'PLAN_PROVIDER_BUDGET_EXHAUSTED';
  end if;

  insert into public.maxxis_provider_budget_usage(user_id, property_id, plan, bucket)
  values (p_user_id, p_property_id, v_plan, v_bucket)
  returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.ds_upsert_property_intelligence_cache(p_property_id uuid, p_provider text, p_provider_property_id text, p_data_type text, p_schema_version smallint, p_payload jsonb, p_retrieved_at timestamp with time zone, p_expires_at timestamp with time zone, p_address_fingerprint text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cache_id uuid;
begin
 if p_address_fingerprint is null or p_address_fingerprint !~ '^[0-9a-f]{64}$' then
  raise exception 'INVALID_ADDRESS_FINGERPRINT';
 end if;
 cache_id := public.ds_upsert_property_intelligence_cache(p_property_id,p_provider,p_provider_property_id,p_data_type,p_schema_version,p_payload,p_retrieved_at,p_expires_at);
 update public.property_intelligence_cache set address_fingerprint=p_address_fingerprint where id=cache_id;
 return cache_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.ds_upsert_property_intelligence_cache(p_property_id uuid, p_provider text, p_provider_property_id text, p_data_type text, p_schema_version smallint, p_payload jsonb, p_retrieved_at timestamp with time zone, p_expires_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_cache_id uuid;
begin
  if p_provider <> 'rentcast' or p_data_type not in ('property_record', 'property_value_avm', 'property_sold_record_pool',
     'property_sold_record_pool_exit_sfr', 'property_sold_record_pool_exit_townhouse', 'property_sold_record_pool_exit_condo')
     or p_schema_version < 1 or jsonb_typeof(p_payload) <> 'object' or p_expires_at <= p_retrieved_at then
    raise exception using errcode = '22023', message = 'INVALID_PROPERTY_INTELLIGENCE_CACHE_ENTRY';
  end if;
  insert into public.property_intelligence_cache
    (property_id, provider, provider_property_id, data_type, schema_version, payload, retrieved_at, expires_at)
    values (p_property_id, p_provider, nullif(trim(p_provider_property_id), ''), p_data_type,
      p_schema_version, p_payload, p_retrieved_at, p_expires_at)
    on conflict (property_id, provider, data_type) do update set provider_property_id = excluded.provider_property_id,
      schema_version = excluded.schema_version, payload = excluded.payload, retrieved_at = excluded.retrieved_at,
      expires_at = excluded.expires_at, updated_at = now() returning id into v_cache_id;
  return v_cache_id;
end;
$function$
